import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Alert from 'flarum/common/components/Alert';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { vapidResetPending } from '../utils/vapidReset';
export default class PWAStatus extends Component {
  loading = true;
  failed = false;
  messages = [];
  oninit(vnode) {
    super.oninit(vnode);
    this.refresh();
  }
  view() {
    if (this.loading) {
      return m("div", {
        className: "Form-group PWAStatus"
      }, m(LoadingIndicator, {
        display: "inline"
      }));
    }
    return m("div", {
      className: "Form-group PWAStatus"
    }, this.failed ? m(Alert, {
      type: "error",
      dismissible: false
    }, app.translator.trans('fof-pwa.admin.status.check_failed')) : this.messages.map(message => m(Alert, {
      key: message.message,
      type: message.type,
      dismissible: false
    }, message.message)));
  }
  refresh() {
    this.loading = true;
    this.failed = false;

    // Checked after a reset in progress, so the keys it makes are seen.
    Promise.resolve(vapidResetPending()).catch(() => {}).then(() => app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/pwa/settings'
    })).then(response => {
      this.messages = response.status_messages;
    }).catch(() => {
      this.failed = true;
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('fof-pwa', 'admin/components/PWAStatus', PWAStatus);