import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
import { resetVapidKeys, vapidResetPending } from '../utils/vapidReset';
export default class PWAResetVapid extends Component {
  view() {
    return m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button",
      loading: !!vapidResetPending(),
      onclick: this.reset.bind(this)
    }, app.translator.trans('fof-pwa.admin.pwa.maintenance.reset_vapid_button')), m("div", {
      className: "helpText"
    }, app.translator.trans('fof-pwa.admin.pwa.maintenance.reset_vapid_text')));
  }
  reset() {
    if (vapidResetPending() || !confirm(extractText(app.translator.trans('fof-pwa.admin.pwa.maintenance.reset_vapid_confirm')))) return;
    resetVapidKeys().then(count => {
      app.alerts.show({
        type: 'success'
      }, app.translator.trans('fof-pwa.admin.pwa.maintenance.reset_vapid_success', {
        count
      }));
    }).catch(() => {}).finally(() => m.redraw());
  }
}
flarum.reg.add('fof-pwa', 'admin/components/PWAResetVapid', PWAResetVapid);