import app from 'flarum/admin/app';

/**
 * The VAPID key reset in progress. Kept outside the components, as switching
 * tabs recreates them while it runs.
 */
let pending = null;
export function vapidResetPending() {
  return pending;
}
export function resetVapidKeys() {
  pending ??= app.request({
    method: 'POST',
    url: app.forum.attribute('apiUrl') + '/reset_vapid'
  }).then(response => response.deleted).finally(() => {
    pending = null;
  });
  return pending;
}
flarum.reg.add('fof-pwa', 'admin/utils/vapidReset', { vapidResetPending: vapidResetPending,resetVapidKeys: resetVapidKeys, });